fn balanced(s) {
    let stack = [];
    for (let i = 0; i < len(s); i++) {
        let c = s[i];
        if (c == "(" || c == "[" || c == "{") {
            push(stack, c);
        } else if (c == ")" || c == "]" || c == "}") {
            if (len(stack) == 0) {
                return false;
            }
            let top = pop(stack);
            if (c == ")" && top != "(") { return false; }
            if (c == "]" && top != "[") { return false; }
            if (c == "}" && top != "{") { return false; }
        }
    }
    return len(stack) == 0;
}

