// Sieve of Eratosthenes: primes below 50.
let n = 50;

// isPrime[i] is true until i is shown to be composite.
let isPrime = [];
for (let i = 0; i < n; i++) {
    push(isPrime, true);
}
isPrime[0] = false;
isPrime[1] = false;

// Mark multiples of each prime p, starting at p * p.
for (let p = 2; p * p < n; p++) {
    if (isPrime[p]) {
        for (let j = p * p; j < n; j += p) {
            isPrime[j] = false;
        }
    }
}

// Collect the remaining primes.
let primes = [];
for (let i = 2; i < n; i++) {
    if (isPrime[i]) {
        push(primes, i);
    }
}

print(primes);

// Caesar cipher: shift each lowercase letter 3 places forward, wrapping z to c.
// Spaces are copied unchanged.
let s = "hello world";
let out = "";

for (let i = 0; i < len(s); i++) {
    let ch = s[i];
    if (ch == " ") {
        out = out + " ";
    } else {
        let code = ord(ch) - 97;          // 0 for 'a', 25 for 'z'
        let shifted = (code + 3) % 26;    // wrap around the alphabet
        out = out + chr(shifted + 97);
    }
}

print(out);

// Returns true when b uses exactly the same letters as a (lowercase words).
fn isAnagram(a, b) {
    if (len(a) != len(b)) {
        return false;
    }

    // One counter per letter a..z.
    let counts = [];
    for (let i = 0; i < 26; i++) {
        push(counts, 0);
    }

    // Count letters of a upward.
    for (let i = 0; i < len(a); i++) {
        let k = ord(a[i]) - ord("a");
        counts[k] += 1;
    }

    // Count letters of b downward.
    for (let i = 0; i < len(b); i++) {
        let k = ord(b[i]) - ord("a");
        counts[k] -= 1;
    }

    // Any non-zero counter means the letters differ.
    for (let i = 0; i < 26; i++) {
        if (counts[i] != 0) {
            return false;
        }
    }
    return true;
}

