fn binarySearch(xs, target, lo = 0, hi = len(xs)) {
    if (hi <= lo) {
        return -1
    }
    let mid = lo + int((hi - lo) / 2)
    if xs[mid] < target {
        return binarySearch(xs, target, mid + 1, hi)
    } else if xs[mid] > target {
        return binarySearch(xs, target, lo, mid)
    } else {
        return mid
    }
}

fn search(xs, target) {
    return binarySearch(xs, target)
}

