fn reverse_words(x) {
    let words = str(x);
    let reversed = "";
    for i from 0 to len(words) - 1 do {
        if words[i] == " " then {
            let new_word = words[i + 1] + reversed;
            reversed = new_word + reversed;
            if i + 1 < len(words) then {
                i += 1;
            }
        }
        if i + 1 == len(words) then {
            let new_word = words[i];
            reversed += new_word + reversed;
        }
    }
    return reversed;
}

