fn balanced(s) {
    stack = [];                   // initialize stack as an empty array
    openers = ['(', '[', '{'];   // array of opening brackets
    closers = [')', ']', '}'];  // corresponding closing brackets

    for char in s {
        if in openers[char] {
            push stack, char;     // push opening brackets onto stack
        } else if in closers[char] {
            if stack is empty or not (pop stack = match in closers[char]) {  // check for matching parentheses
                return false;      // if no match or stack is empty, return false
            }
        }
    }
    return stack is empty;         // if stack is empty, all brackets are balanced
}

