fn multiply(A, B) {
    let sum = 0;
    let len = len(A);
    let result = [];
    for (let i = 0; i < len; i++) {
       result[i] = [];
       for (let j = 0; j < len; j++) {
          for (let k = 0; k < len; k++) {
             sum += int(A[i][k]) * int(B[k][j]);
          }
          result[i][j] = sum;
          sum = 0;
       }
    }
    return result;
}

