fn sieve(n) {
    let primes = [false, false] + make_array(n - 2);
    for (let i = 2; i <= n; i++) {
        if (!primes[i]) {
            print("i", i);
            let j = i * 2;
            while (j <= n) {
                print("j", j);
                primes[j] = true;
                j += i;
            }
        }
    }
    for (let i = 2; i <= n; i++) {
        if (!primes[i]) {
            print("primes[i]", i);
        }
    }
}

