fn search(xs, target) {
    if low > high {
        return -1
    }
    mid = (low + high) // 2
    if xs[mid] == target {
        return mid
    }
    if target < xs[mid] {
        return bisect_search(xs, target, low, mid - 1)
    } else {
        return bisect_search(xs, target, mid + 1, high)
    }
}
fn bisect_search(xs, target, low=0, high=len(xs) - 1) {
    if low > high {
        return -1
    }
    mid = (low + high) // 2
    if xs[mid] == target {
        return mid
    }
    if target < xs[mid] {
        return bisect_search(xs, target, low, mid - 1)
    } else {
        return bisect_search(xs, target, mid + 1, high)
    }
}
fn main() {
    print(search([], 2))   // -1
    print(search([2, 5, 8, 12, 16, 23, 38, 56, 72, 91], 23))   // 5
    print(search([2, 5, 8, 12, 16, 23, 38, 56, 72, 91], 7))  // -1
    print(search([2, 5, 8, 12, 16, 23, 38, 56, 72, 91], 91))  // 9
}
