fn sieve(n) {
    let marked = [true] * n;
    let primes = [];

    for (let i = 2; i < n; i++) {
        if (marked[i]) {
            primes.push(i);
            for (let j = i * i; j < n; j += i) {
                marked[j] = false;
            }
        }
    }
    return primes;
}

