classify = fn(limit) {
    let is_prime = new Array(limit+1).fill(true);
    is_prime[0] = false;
    is_prime[1] = false;
    for (let i = 2; i <= Math.sqrt(limit); i++) {
        if (is_prime[i]) {
            for (let j = i*i; j <= limit; j += i) {
                is_prime[j] = false;
            }
        }
    }
    return is_prime.map((n, idx) => n).filter(Boolean);
}
