fn pascals_triangle(n) {
    let triangle = [[]];
    for (let i = 0; i < n; i++) {
        let prev_row = triangle[i];
        let current_row = [1];
        for (let j = 1; j < i; j++) {
            current_row[j] = prev_row[j - 1] + prev_row[j];
        }
        current_row.push(1);
        triangle.push(current_row);
    }
    return triangle;
}

