fn caesarEncrypt(s) {
    let encrypted = "";
    for (let i = 0; i < len(s); i++) {
        let c = s[i];
        if (c == " ") {
            encrypted += c; // Leave spaces unchanged
        } else if ('a' <= c && c <= 'z') {
            // Calculate shifted character
            let shifted = chr((abs(97 + 25 - ord(c) + 3) % 26) + 97);
            encrypted += shifted;
        } else {
            // Non-alphabetic characters are added unchanged
            encrypted += c;
        }
    }
    return encrypted;
}

