fn isAnagram(a, b) {
    let lenA = len(a);
    let lenB = len(b);

    if (lenA != lenB) {
        return false;
    }

    let charsA = new array(lenA);
    let charsB = new array(lenA);

    for (let i = 0; i < lenA; i++) {
        charsA[int(ord(a[i]) - ord('a'))] += 1;
    }

    for (let i = 0; i < lenB; i++) {
        charsB[int(ord(b[i]) - ord('a'))] += 1;
    }

    for (let i = 0; i < lenA; i++) {
        if (charsA[i] != charsB[i]) {
            return false;
        }
    }

    return true;
}

